const Hh = 12, Bb = 15;
check('Table 25 periods for H = 12 m and B = 15 m: masonry 0.0994, shear walls 0.1652, RC frames 0.2789, steel frames 0.3098 s', ['mas', 'sw', 'rc', 'st'].map(t => +w.eval('joSmPeriod("' + t + '", 12, 15)').toFixed(4)).join(), [0.06 * Hh / Math.sqrt(Bb) * Math.sqrt(Hh / (2 * Bb + Hh)), 0.08 * Hh / Math.sqrt(Bb) * Math.sqrt(Hh / (Bb + Hh)), 0.09 * Hh / Math.sqrt(Bb), 0.1 * Hh / Math.sqrt(Bb)].map(x => +x.toFixed(4)).join());
check('Table 24: 0.05 / cbrt T gives 0.0765 at T 0.2788 and is limited to 0.10 at T 0.1 and to 0.04 at T 2.0; the 0.06 row is limited to 0.12 and 0.05; the slender row to 0.2 and 0.06; low structures are 0.1', [+w.eval('joSmBeta("part", 0.2788)').toFixed(4), w.eval('joSmBeta("part", 0.1)'), w.eval('joSmBeta("part", 2)'), w.eval('joSmBeta("store", 0.01)'), w.eval('joSmBeta("store", 9)'), w.eval('joSmBeta("slim", 0.01)'), w.eval('joSmBeta("slim", 9)'), w.eval('joSmBeta("low", 0.3)')], [0.0765, 0.1, 0.04, 0.12, 0.05, 0.2, 0.06, 0.1]);
check('soil factor: 1.3 when Ts is not below T, 0.7 / cbrt (0.3) = 1.046 at T 0.5 and Ts 0.2, limited to 0.8 for T 1.0 and Ts 0', [w.eval('joSmDelta(0.2788, 0.4)'), +w.eval('joSmDelta(0.5, 0.2)').toFixed(3), w.eval('joSmDelta(1, 0)'), w.eval('joSmDelta(0.3, 0.3)')], [1.3, 1.046, 0.8, 1.3]);
check('tables: zones 0.75 / 0.50 / 0.30 / 0.10, behaviour 1.00 0.67 1.33 0.80 1.33 2.50 3.00, importance 1.30 1.20 1.00, K 0 0.25 1.0, Ts 0.2 / 0.4 / 0.4 - 0.8 / 0.4 - 1.4 / 1.4, parts 0.2 2.0 1.0 1.0 0.2', [w.eval('Object.values(JO_SM_ALPHA).join()'), w.eval('JO_SM_THETA.map(x => x[2]).join()'), w.eval('JO_SM_ETA.map(x => x[2]).join()'), w.eval('JO_SM_K.map(x => x[2]).join()'), w.eval('JO_SM_SOIL.map(x => x[2] + "-" + x[3]).join()'), w.eval('JO_SM_C.map(x => x[2]).join()')], ['0.75,0.5,0.3,0.1', '1,0.67,1.33,0.8,1.33,2.5,3', '1.3,1.2,1', '0,0.25,1', '0.2-0.2,0.4-0.4,0.4-0.8,0.4-1.4,1.4-1.4', '0.2,2,1,1,0.2']);
