const T0 = 0.09 * 12 / Math.sqrt(15), b0 = 0.05 / Math.cbrt(T0), sg = 3000 * (1 / 3 + 2 / 3 + 1) + 2500 * 4 / 3, V0 = 0.5 * b0 * 1.3 * 0.67 * 1 * sg, J0 = 0.6 / Math.cbrt(T0);
check('RC frame, zone B, soil 2, 4 floors of 3000 kN and a 2500 kN roof (K = 0): T 0.279, beta 0.0765, delta 1.3, gamma 1/3, 2/3, 1, 4/3 and V = 0.5 x beta x 1.3 x 0.67 x sum(gamma W)', [+sm.T.toFixed(4), +sm.beta.toFixed(4), sm.delta, sm.gamma.map(g => +g.toFixed(3)).join(), +sm.sgw.toFixed(1), +sm.V.toFixed(2)], [+T0.toFixed(4), +b0.toFixed(4), 1.3, '0.333,0.667,1,1.333', +sg.toFixed(1), +V0.toFixed(2)]);
const sFh = sm.F.reduce((a, f, i) => a + f * (i + 1) * 3, 0);
check('the floor forces add up to V and rise with the height; the overturning moment is J x sum(F h) with J = 0.6 / cbrt T = 0.918; M_z falls linearly to zero at the top', [+sm.F.reduce((a, b) => a + b, 0).toFixed(3), sm.F.every((f, i) => i === 0 || f > sm.F[i - 1]), +sm.J.toFixed(4), +sm.MB.toFixed(1), +sm.Mz[0].toFixed(1), sm.Mz[3]], [+sm.V.toFixed(3), true, +J0.toFixed(4), +(J0 * sFh).toFixed(1), +(0.75 * J0 * sFh).toFixed(1), 0]);
check('K = 0.25 adds a quarter of the live loads: W = 3200 and 2575 kN, so the base shear grows; zone D has 0.1 / 0.5 of zone B; importance 1.3 scales V by 1.3', [smc({occ: '1'}).W.join(), smc({occ: '1'}).V > sm.V, +(smc({zone: 'D'}).V / sm.V).toFixed(3), +(smc({imp: '1'}).V / sm.V).toFixed(3)], ['3200,3200,3200,2575', true, 0.2, 1.3]);
sm = smc({n: 5, hs: 3, Ds: 3, stype: 'x', T: 0.6});
check('a 15 m tower with a main bracing element 3 m deep has H / Ds = 5 > 3: the extra force dF = 0.004 x 25 V = 0.1 V (below 0.15 V) goes to the top and the floors share V - dF', [sm.HDs, +(sm.dF / sm.V).toFixed(3), +sm.F.reduce((a, b) => a + b, 0).toFixed(3), sm.Tover, sm.T], [5, 0.1, +sm.V.toFixed(3), true, 0.6]);
